def escape_special_characters(input_string):
    """
    Replaces special characters in the input string with their corresponding HTML entities.

    Parameters:
    input_string (str): The string to be processed.

    Returns:
    str: The processed string with special characters replaced.
    """
    result = []
    i = 0
    while i < len(input_string):
        char = input_string[i]
        if char == '&':
            result.append('&amp;')
        elif char == '>':
            result.append('&gt;')
        elif char == '<':
            result.append('&lt;')
        elif char == '"':
            result.append('&quot;')
        elif char == "'":
            result.append('&apos;')
        elif char == '(':
            result.append('&lpar;')
        elif char == ')':
            result.append('&rpar;')
        else:
            result.append(char)
        i += 1
    return ''.join(result)
