def flatten_and_convert(lst):
    """
    Flattens a nested list and converts all strings to their ASCII values.

    :param lst: A nested list containing integers and strings.
    :return: A flattened list with strings replaced by their ASCII values.
    """
    def is_integer(value):
        return isinstance(value, int) and not isinstance(value, bool)

    def is_string(value):
        return isinstance(value, str)

    def get_ascii_value(char):
        return ord(char)

    def flatten(lst):
        for item in lst:
            if is_integer(item):
                yield item
            elif is_string(item):
                for char in item:
                    yield get_ascii_value(char)
            else:
                yield from flatten(item)

    return list(flatten(lst))
```

