def validBrackets(s: str) -> bool:
    """
    Determines if the input string s contains valid brackets.

    :param s: A string consisting of characters '(', ')', '{', '}', '[', and ']'.
    :return: True if the string contains valid brackets, False otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or bracket_map[char] != stack.pop():
                return False

    return not stack
