def create_triangle_dict(n):
    """
    Constructs a dictionary where each key k (0 <= k < n) is mapped to a list of k+1 consecutive prime numbers.

    Parameters:
    n (int): The number of keys in the dictionary.

    Returns:
    dict: A dictionary with keys from 0 to n-1 and values as lists of consecutive prime numbers.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def get_primes(count):
        primes = []
        candidate = 2
        while len(primes) < count:
            if is_prime(candidate):
                primes.append(candidate)
            candidate += 1
        return primes

    result = {}
    total_primes_needed = n * (n + 1) // 2
    all_primes = get_primes(total_primes_needed)

    index = 0
    for k in range(n):
        result[k] = all_primes[index:index + k + 1]
        index += k + 1

    return result
