def filter_and_extract(query_filter, query_extract, products):
    """
    Filters products based on query_filter and extracts specified attributes using query_extract.

    :param query_filter: Dictionary specifying the criteria for filtering products.
    :param query_extract: List specifying the attributes to extract from each product.
    :param products: List of dictionaries, where each dictionary represents a product.
    :return: List of dictionaries with extracted attributes from products that match the filter criteria.
    """
    def matches_filter(product):
        """
        Checks if a product matches the filter criteria.

        :param product: Dictionary representing a product.
        :return: True if the product matches the filter criteria, False otherwise.
        """
        for key, value in query_filter.items():
            if isinstance(value, dict):
                nested_value = get_nested_value(product, list(value.keys()))
                if nested_value is None or not all(nested_value.get(k) == v for k, v in value.items()):
                    return False
            elif product.get(key) != value:
                return False
        return True

    def extract_attributes(product):
        """
        Extracts specified attributes from a product.

        :param product: Dictionary representing a product.
        :return: Dictionary with extracted attributes.
        """
        extracted = {}
        for attr in query_extract:
            if isinstance(attr, dict):
                keys = list(attr.keys())[0]
                nested_keys = list(attr[keys].keys())
                nested_value = get_nested_value(product, nested_keys)
                if nested_value is not None:
                    extracted[keys] = nested_value
            else:
                extracted[attr] = product.get(attr)
        return extracted

    result = []
    for product in products:
        if matches_filter(product):
            result.append(extract_attributes(product))
    return result
