import json

def find_node(json_str, target):
    """
    Searches for a node with the specified target name in the tree represented by the JSON string.

    :param json_str: A JSON string representing the tree.
    :param target: The name of the node to find.
    :return: The dictionary representation of the node with the specified name if it exists, otherwise None.
    """
    def search(node):
        if node['name'] == target:
            return node
        for child in node.get('children', []):
            result = search(child)
            if result:
                return result
        return None

    tree = json.loads(json_str)
    return search(tree)
