def convert_to_integer(s, strict=False, default=None):
    """
    Converts a string to an integer, handling multiple number bases and formatting rules.

    Parameters:
    s (str): The string to convert.
    strict (bool): If True, only convert strings that strictly adhere to the format for a given number base.
    default: The value to return if the conversion fails and strict is False.

    Returns:
    int or default: The converted integer or the default value if conversion fails.
    """
    s = s.strip()
    if not s:
        return default

    if s.startswith('0b'):
        if strict:
            if not s[2:].replace('_', '').lstrip('-').isdigit():
                return default
        return int(s, 2)
    elif s.startswith('0x'):
        if strict:
            if not s[2:].replace('_', '').lstrip('-').replace('.', '', 1).isalnum():
                return default
        return int(s, 16)
    elif s.startswith('0o'):
        if strict:
            if not s[2:].replace('_', '').lstrip('-').isdigit():
                return default
        return int(s, 8)
    elif s.startswith('0') and s[1:].replace('_', '').lstrip('-').isdigit():
        if strict:
            if not s[1:].replace('_', '').lstrip('-').isdigit():
                return default
        return int(s, 8)
    elif s.replace('_', '').lstrip('-').replace('.', '', 1).isalnum():
        if strict:
            if not s.replace('_', '').lstrip('-').replace('.', '', 1).isalnum():
                return default
        return int(s)
    else:
        return default
```

