def count_divisors(n):
    """
    Returns the number of divisors of the given integer n.

    :param n: Integer for which to count the divisors.
    :return: Number of divisors of n.
    """
    if n <= 0:
        return 0  # No divisors for non-positive integers

    count = 0
    sqrt_n = int(n**0.5)

    for i in range(1, sqrt_n + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2

    return count
