def is_balanced(expression: str) -> bool:
    """
    Determines if the parentheses, square brackets, and curly braces in the string are balanced.

    :param expression: A string containing only the characters '()[]{}'.
    :return: True if the expression is balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or matching_bracket[char] != stack.pop():
                return False

    return not stack
