def prime_factors(n):
    """Find all prime factors of a number."""
    factors = set()
    while n % 2 == 0:
        factors.add(2)
        n //= 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.add(i)
            n //= i
    if n > 2:
        factors.add(n)
    return factors

def lcm_prime_factors(arr):
    """Find all distinct prime factors of the LCM of the array."""
    lcm_factors = set()
    for num in arr:
        lcm_factors.update(prime_factors(num))
    return sorted(lcm_factors)

