def transpose_graph(graph):
    """
    Computes the transpose of a directed graph represented as an adjacency list.

    :param graph: A dictionary representing the adjacency list of the graph.
    :return: A dictionary representing the adjacency list of the transposed graph.
    """
    transposed_graph = {}
    for node in graph:
        if node not in transposed_graph:
            transposed_graph[node] = []
    for node in graph:
        for neighbor in graph[node]:
            if neighbor not in transposed_graph:
                transposed_graph[neighbor] = []
            transposed_graph[neighbor].append(node)
    return transposed_graph
