def fibonacci_Memo(n, memo=None):
    """Return the first n prime Fibonacci numbers using memoization."""
    if n < 0:
        return [-1]
    if memo is None:
        memo = {}
    if n == 0:
        return []
    if n in memo:
        return memo[n]

    fib_sequence = [0, 1]
    prime_fib_sequence = []

    while len(prime_fib_sequence) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_fib)
        if is_prime(next_fib):
            prime_fib_sequence.append(next_fib)

    memo[n] = prime_fib_sequence
    return prime_fib_sequence
