def evaluate_rpn(tokens):
    """
    Evaluates a boolean expression given in Reverse Polish Notation (RPN).

    :param tokens: List of tokens representing the RPN expression.
    :return: Boolean result of the evaluated expression.
    """
    stack = []
    operators = {'+', '|', '^', '!'}

    for token in tokens:
        if token in operators:
            if token == '!':
                operand = stack.pop()
                stack.append(not operand)
            else:
                operand2 = stack.pop()
                operand1 = stack.pop()
                if token == '+':
                    stack.append(operand1 and operand2)
                elif token == '|':
                    stack.append(operand1 or operand2)
                elif token == '^':
                    stack.append(operand1 != operand2)
        else:
            stack.append(token)

    return stack.pop()
```

