def flatten_tuple(items):
    """
    Flattens a given tuple or list, including nested structures, into a single tuple.
    If the input is a single item, returns a tuple containing that item.

    :param items: A single item, tuple, or list to be flattened.
    :return: A flattened tuple of all items.
    """
    def _flatten(items):
