def string_to_ascii(s):
    """
    Convert a string to a list of ASCII values.

    :param s: Input string
    :return: List of ASCII values
    """
    ascii_values = []
    for char in s:
        ascii_value = 0
        for bit in range(8):
            ascii_value += (ord(char) >> bit) & 1 << (7 - bit)
        ascii_values.append(ascii_value)
    return ascii_values

def replace_strings_with_ascii(data):
    """
    Recursively replace strings in a nested data structure with lists of ASCII values.

    :param data: Nested dictionary with strings, lists, and other nested dictionaries
    :return: Modified nested dictionary with strings replaced by ASCII lists
    """
    if isinstance(data, dict):
        return {key: replace_strings_with_ascii(value) for key, value in data.items()}
    elif isinstance(data, list):
        return [replace_strings_with_ascii(item) for item in data]
    elif isinstance(data, str):
        return string_to_ascii(data)
    else:
        return data
