    Convert a given string into a specified case type.

    :param name: The input string consisting of alphanumeric characters, spaces, and hyphens.
    :param case_type: The target case type, which can be 'snake', 'camel', 'kebab', or 'pascal'.
    :return: The transformed string in the specified case type.
    :raises ValueError: If the case_type is not one of the specified types.
    """
    if case_type == 'snake':
        return name.lower().replace('-', '_')
    elif case_type == 'camel':
        parts = name.split()
        return parts[0].lower() + ''.join(word.capitalize() for word in parts[1:])
    elif case_type == 'kebab':
        return name.lower().replace('_', '-')
    elif case_type == 'pascal':
        parts = name.split()
        return ''.join(word.capitalize() for word in parts)
    else:
        raise ValueError("Invalid case type. Please use 'snake', 'camel', 'kebab', or 'pascal'.")
