def days_between_dates(start_date, end_date):
    """
    Computes the total number of days between two dates, inclusive.

    :param start_date: A string representing the start date in "YYYY-MM-DD" format.
    :param end_date: A string representing the end date in "YYYY-MM-DD" format.
    :return: An integer representing the total number of days between the start date and the end date, inclusive.
    """
    def parse_date(date_str):
        year, month, day = map(int, date_str.split('-'))
        return year, month, day

    start_year, start_month, start_day = parse_date(start_date)
    end_year, end_month, end_day = parse_date(end_date)

    total_days = 0

    while start_year < end_year:
        total_days += days_in_month(start_year, 12)
        start_year += 1

    while start_month < end_month:
        total_days += days_in_month(start_year, start_month)
        start_month += 1

    total_days += end_day - start_day + 1

    return total_days
