import json

def extract_value_from_json(json_str, key):
    """
    Extracts the value associated with a specified key from a JSON string.

    Parameters:
    json_str (str): A JSON string representing the JSON document.
    key (str): The key whose value needs to be extracted.

    Returns:
    The value associated with the key if found, otherwise None.
    """
    data = json.loads(json_str)

    def recursive_search(obj, key):
        if isinstance(obj, dict):
            if key in obj:
                return obj[key]
            for k, v in obj.items():
                result = recursive_search(v, key)
                if result is not None:
                    return result
        elif isinstance(obj, list):
            for item in obj:
                result = recursive_search(item, key)
                if result is not None:
                    return result
        return None

    return recursive_search(data, key)
