def recursive_palindrome(s: str) -> bool:
    """
    Determines if the given string is a palindrome, ignoring non-alphanumeric characters and case differences.

    :param s: The input string to check.
    :return: True if the string is a palindrome, False otherwise.
    """
    def is_palindrome(s: str, left: int, right: int) -> bool:
        if left >= right:
            return True
        if not s[left].isalnum():
            return is_palindrome(s, left + 1, right)
        if not s[right].isalnum():
            return is_palindrome(s, left, right - 1)
        if s[left].lower() != s[right].lower():
            return False
        return is_palindrome(s, left + 1, right - 1)

    return is_palindrome(s, 0, len(s) - 1)
