def find_path(dictionary, keys):
    """
    Returns a list of all unique paths in the dictionary that lead to a value associated with the given keys.

    :param dictionary: A nested dictionary where keys are strings and values can be either integers or other dictionaries.
    :param keys: A list of keys for which you need to find paths.
    :return: A list of lists, where each inner list represents a unique path in the dictionary leading to a value associated with one of the given keys.
    """
    def search_paths(d, target_keys, path=None):
        if path is None:
            path = []
        paths = []
        for key, value in d.items():
            new_path = path + [key]
            if key in target_keys:
                paths.append(new_path)
            elif isinstance(value, dict):
                paths.extend(search_paths(value, target_keys, new_path))
        return paths

    return search_paths(dictionary, keys)
